#!/bin/sh
# run.sh - one invocation of a calibration cell in a throwaway container (the driver's argv entry point).
# usage: run.sh probe|pair|later <lat|thr> <N> [--pin CPUS] [--sibling CPU] [--antagonist CPU] [--kernel]
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'cpu-measurement-calibration/run.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'run.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  cat <<'USAGE'
usage: run.sh probe <lat|thr> <N> [options]   one fresh container: scripts/cpuprobe.sh around `work MODE N`
       run.sh later <lat|thr> <N> [options]   one fresh container: the probe runs twice, only the second is emitted
       run.sh pair  <lat|thr> <N> [options]   one fresh container: the probe runs twice, both emitted (first_*, second_*)
       run.sh cpu-online <CPU> <0|1>          write /sys/devices/system/cpu/cpuCPU/online through a privileged container
       run.sh cpu-state <CPU>                 print the online file of CPU (1 when it has none)
       run.sh --help | --build | --version
options: --pin CPUS         docker --cpuset-cpus CPUS (default: unpinned)
         --sibling CPU      pass --sibling CPU to the probe (sibling_busy)
         --antagonist CPU   run `work MODE 100000000000` in its own container pinned to CPU for the whole invocation
         --kernel           pass --kernel to the probe
Uses the cpucal:1 image (build it with: docker build -t cpucal:1 cpu-measurement-calibration), --rm, --cap-add PERFMON
--cap-add SYS_ADMIN (counters in Docker), forwards MEASURE_PAD, and prints the probe's MEASURE lines plus
`MEASURE cpuset_ncpus K` and a `cpus_allowed_list L` line (the container's effective cpuset). The probe is
$CAL_PROBE (default ../scripts/cpuprobe.sh beside this folder). cpu-online refuses CPU 0.
USAGE
  exit 0
fi
set -eu

HERE=$(cd "$(dirname "$0")" && pwd)
case ${1:-} in
  --build|--version) exec "$HERE/../scripts/cpuprobe.sh" --build ;;
esac
PROBE=${CAL_PROBE:-$HERE/../scripts/cpuprobe.sh}
IMG=cpucal:1
die() { echo "run.sh: $*" >&2; exit 2; }
num() { case ${1:-} in ''|*[!0-9]*) die "'${1:-}' is not a non-negative whole number" ;; esac; }

mode=${1:?mode (try --help)}
case $mode in
  cpu-online)
    cpu=${2:?CPU}; val=${3:?0|1}; num "$cpu"
    [ "$cpu" != 0 ] || die "refusing to change cpu0"
    case $val in 0|1) ;; *) die "value must be 0 or 1" ;; esac
    exec docker run --rm --privileged "$IMG" sh -c "echo $val > /sys/devices/system/cpu/cpu$cpu/online" ;;
  cpu-state)
    cpu=${2:?CPU}; num "$cpu"
    exec docker run --rm "$IMG" sh -c "if [ -r /sys/devices/system/cpu/cpu$cpu/online ]; then cat /sys/devices/system/cpu/cpu$cpu/online; else echo 1; fi" ;;
  probe|later|pair) ;;
  *) die "unknown mode '$mode' (try --help)" ;;
esac
wl=${2:?lat|thr}; n=${3:?N}
case $wl in lat|thr) ;; *) die "workload must be lat or thr" ;; esac
num "$n"
shift 3
pin=; sib=; ant=; kern=
while [ $# -gt 0 ]; do
  case $1 in
    --pin) [ $# -ge 2 ] || die "--pin needs a value"; pin=$2; shift 2 ;;
    --sibling) [ $# -ge 2 ] || die "--sibling needs a value"; num "$2"; sib=$2; shift 2 ;;
    --antagonist) [ $# -ge 2 ] || die "--antagonist needs a value"; num "$2"; ant=$2; shift 2 ;;
    --kernel) kern=--kernel; shift ;;
    *) die "unknown option '$1'" ;;
  esac
done
[ -r "$PROBE" ] || die "probe not found at $PROBE"
pa=$kern
[ -z "$sib" ] || pa="$pa --sibling $sib"
pinarg=; [ -z "$pin" ] || pinarg="--cpuset-cpus $pin"

# runs inside the container: report the effective cpuset, then the probe once, twice (later) or twice with prefixes (pair)
INNER='cl=$(sed -n "s/^Cpus_allowed_list:[[:space:]]*//p" /proc/self/status)
echo "cpus_allowed_list $cl"
echo "$cl" | awk "{ k = split(\$0, a, \",\"); t = 0; for (i = 1; i <= k; i++) { m = split(a[i], r, \"-\"); t += (m == 2) ? r[2] - r[1] + 1 : 1 }; print \"MEASURE cpuset_ncpus \" t }"
P=/probe/cpuprobe.sh
case $PHASE in
  probe) exec $P $PA -- work $WL $N ;;
  later) $P $PA -- work $WL $N >/dev/null; exec $P $PA -- work $WL $N ;;
  pair)
    rc=0; $P $PA -- work $WL $N >/tmp/o1 || rc=$?
    if [ $rc -ne 0 ]; then cat /tmp/o1; exit $rc; fi
    $P $PA -- work $WL $N >/tmp/o2 || rc=$?
    sed "s/^MEASURE /MEASURE first_/" /tmp/o1; sed "s/^MEASURE /MEASURE second_/" /tmp/o2; exit $rc ;;
esac'

name=
cleanup() { if [ -n "$name" ]; then docker rm -f "$name" >/dev/null 2>&1 || true; fi; }
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
if [ -n "$ant" ]; then
  name=cpucal-ant-$$
  docker run -d --name "$name" --cpuset-cpus "$ant" "$IMG" work "$wl" 100000000000 >/dev/null
  sleep 0.5
fi
rc=0
# shellcheck disable=SC2086
docker run --rm --cap-add PERFMON --cap-add SYS_ADMIN $pinarg -e "MEASURE_PAD=${MEASURE_PAD:-}" \
  -e "PHASE=$mode" -e "PA=$pa" -e "WL=$wl" -e "N=$n" -v "$PROBE:/probe/cpuprobe.sh:ro" "$IMG" sh -c "$INNER" || rc=$?
exit "$rc"
